{
    "@context": "https://schema.org",
    "@type": "FAQPage",
    "mainEntity": [
        {
            "@type": "Question",
            "name": "What are seamless surfaces?",
            "acceptedAnswer": {
                "@type": "Answer",
                "text": "Seamless surfaces use microcement, tadelakt, and luxury plaster coatings applied directly over your existing walls, floors, and counters. No demolition. No grout lines. Just one smooth, continuous, waterproof surface that's faster to install and easier to maintain than traditional tile or stone."
            }
        },
        {
            "@type": "Question",
            "name": "How much does a microcement bathroom cost in New Orleans?",
            "acceptedAnswer": {
                "@type": "Answer",
                "text": "Most single-room seamless surface upgrades in the Greater New Orleans area run between $2,000 and $8,000 depending on square footage, prep work, and finish selection. Full multi-room transformations start at $8,000. The Seamless Studio gives you a free instant cost estimate for your specific space."
            }
        },
        {
            "@type": "Question",
            "name": "Is microcement waterproof?",
            "acceptedAnswer": {
                "@type": "Answer",
                "text": "Yes. Properly applied and sealed microcement is 100% waterproof and is regularly used in walk-in showers, wet rooms, pool decks, and exterior wet zones. No grout means no failure points where water can penetrate."
            }
        },
        {
            "@type": "Question",
            "name": "Can microcement be installed over existing tile?",
            "acceptedAnswer": {
                "@type": "Answer",
                "text": "Yes. Microcement bonds directly to existing tile, concrete, drywall, and even properly-prepped wood subfloors. No demolition is needed in most cases, which dramatically reduces cost and timeline versus a full tile replacement."
            }
        },
        {
            "@type": "Question",
            "name": "How long does a seamless surface installation take?",
            "acceptedAnswer": {
                "@type": "Answer",
                "text": "Most single-room installs complete in 2 to 5 days depending on scope. The work is done in layers, each curing 12-24 hours before the next. Once the final seal is applied, the surface is fully usable within 48 hours."
            }
        },
        {
            "@type": "Question",
            "name": "Do you serve areas outside New Orleans?",
            "acceptedAnswer": {
                "@type": "Answer",
                "text": "Yes — we serve Greater New Orleans including Metairie, Gretna, Harvey, Lakeview, Uptown, Mid-City, Marigny, Algiers, and the Westbank. For projects further out, text Ryan at 504-264-4919 to discuss."
            }
        },
        {
            "@type": "Question",
            "name": "How does The Seamless Studio work?",
            "acceptedAnswer": {
                "@type": "Answer",
                "text": "Upload a photo of any room — bathroom, kitchen, floor, wall, pool deck, or feature area. Our AI shows you three seamless surface design options for that exact space, complete with material breakdowns and a cost estimate. The whole thing takes about 60 seconds and costs nothing."
            }
        }
    ]
}
